  return /^smartform name$/i.test(norm(row['SmartForm Name'] || row.smart_form_name || ''));
}
function needsBoqFetch(row) {
  return !isTrue(row.BOQ_Checked || row.boq_checked || row['BOQ Checked'] || '');
}

var ojsRows = $('Read Operative Job Sheet3').all().map(function(i) { return i.json || {}; });
var seen = {};
var pending = 0;
var stats = { skipped_done: 0 };

for (var oi = 0; oi < ojsRows.length; oi++) {
  var row = ojsRows[oi];
  if (isHeaderRow(row)) continue;
  var sfn = norm(row['SmartForm Name'] || row.smart_form_name || '');
  if (!sfn) continue;
  var key = sfn.toUpperCase();
  if (seen[key]) continue;
  if (!needsBoqFetch(row)) { stats.skipped_done++; continue; }
  seen[key] = true;
  pending++;
}

if (!pending) {
  return [{ json: {
    _no_jobs: true,
    message: 'No BOQ jobs — ' + stats.skipped_done + ' already BOQ_Checked.',
    stats: stats,
  }}];
